dir:








































































&DefaultButton;




function dir$dmvb_nb(p){
  this.constructor(p);
}
dir$dmvb_nb.prototype = new DirEvent();
dir$dmvb_nb.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmvb_nb.prototype.afterInit = function(renderType){
    var p = this._dir,g = p.options.parent;

	dir$dmvb_nbDisabledMasterField(p, g);
}

function dir$dmvb_nbLoadMaVb(p){
	var maNvb = p.valForm('ma_nvb');

	if(p.options.action == 'NEW') {
		if(maNvb == '') {
			p.valForm('ma_vb', '', true);
			p.jObject('ma_nvb').focus(); 
			$.showToast(p.msg('RequireMaNVB'));

			return;
		}
		p.request('LoadMavb', '', ['ma_nvb', 'ngay_ct']);
	}
}

dir$dmvb_nb.prototype.formFieldValueChange = function(o, cF, v) {
    var p = this._dir;
	switch (cF){
		case 'ngay_ct':
			dir$dmvb_nbLoadMaVb(p);
		break;
		case 'ma_nvb':
			dir$dmvb_nbLoadMaVb(p);
		break;
		default:
		  break;
	}
};

function dir$dmvb_nbDisabledMasterField(p){
	var maVb = p.valForm('ma_vb');
	if (maVb !== '') {
		p.setDisabled('ngay_ct', true);
		p.setDisabled('ma_nvb', true);
	}
	else {
		p.setDisabled('ngay_ct', false);
		p.setDisabled('ma_nvb', false);
	}
}







.modal-dialog-lg{min-width:960px!important;}
.control-label.tt {color: #499b98; text-decoration: underline}
.control-label.ma_pl, .control-label.ma_nvb, .control-label.ngay_ct {color: #499b98;}







EXEC [dbo].[st_CreateDocumentCode] @ngay_ct, @ma_nvb, 'VB';






select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table

declare @script nvarchar(4000)
if @action in ('EDIT', 'VIEW') exec ISWIFTStoreGetListFiles 'xfile', @ma_vb, 'dmvb_nb', '', @script output
if @script is null set @script = ''

select @script as script
drop table #@@table






update @@table set datetime2 = getdate(), user_id2 = @@userId where [%whereFieldKey]
update dmttin set status = 0 from dmttin where id0 = rtrim(@ma_vb) and xgroup = 'dmvb_nb'
if @xfile <> '' update dmttin set status = 1, id0 = @ma_vb from dmttin where charindex(id, @xfile) > 0 and xgroup = 'dmvb_nb'






if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, '@@firstFieldKey' as field
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit, @ma_loai = 'VB', @xstatus = 1






if @xfile <> '' update dmttin set status = 1, id0 = @ma_vb from dmttin where charindex(id, @xfile) > 0 and xgroup = 'dmvb_nb'







update #data set unit_id = @@unit;
update #data set ma_loai = 'VB';
update #data set xstatus = 1;

